                days_per_calendar_year[curr.year] += 1
            curr += one_day

        # Check if the employee has enough remaining days in each involved year
        for year, needed in days_per_calendar_year.items():
            if needed > self.remaining(employee, year):
                raise ValueError(
                    f"Insufficient remaining leave days in {year}: needed {needed}, "
                    f"available {self.remaining(employee, year)}."
                )

        # Deduct leave days
