        """Return the list of (start, end) leave requests for the specified employee."""
        return list(self.employee_requests[employee])

    def remaining(self, employee: str, year: int) -> int:
        used = self.used_leave[employee][year]
        return max(0, self.days_per_year - used)

    def employees(self) -> list[str]:
